import React, { useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';
import { Terminal } from 'xterm';
import { FitAddon } from 'xterm-addon-fit';
import 'xterm/css/xterm.css';

function TerminalComponent() {
  const params = useParams();
  const containerId = params.containerId; // Retrieve container ID from URL params
  const terminalRef = useRef(null); // Ref for the terminal div
  const terminalInstance = useRef(null); // Ref for xterm.js Terminal instance
  const socketRef = useRef(null); // Ref for WebSocket connection
  const fitAddon = useRef(new FitAddon()); // FitAddon instance for xterm.js resizing

  useEffect(() => {
    // Initialize xterm.js Terminal
    terminalInstance.current = new Terminal({
      cursorBlink: true,
      fontSize: 14,
      theme: {
        background: "#000000", // Set background color
        foreground: "#FFFFFF"  // Set text color
      }
    });
    terminalInstance.current.loadAddon(fitAddon.current);

    // Open the terminal in the div
    if (terminalRef.current) {
      terminalInstance.current.open(terminalRef.current);
      fitAddon.current.fit(); // Fit terminal size to the container
    }

    // Initialize WebSocket connection
    socketRef.current = new WebSocket('ws://localhost:3001');

    // WebSocket event listeners
    socketRef.current.onopen = () => {
      console.log('WebSocket connection established');
      // Send initial command to start a shell session in the container
      socketRef.current.send(JSON.stringify({ containerId, cmd: '/bin/sh' }));
    };

    // Handle messages from WebSocket (output from Docker container)
    socketRef.current.onmessage = (event) => {
      const message = JSON.parse(event.data);
      if (message.output) {
        terminalInstance.current.write(message.output); // Display output in terminal
      } else if (message.error) {
        terminalInstance.current.write(`\x1B[31m${message.error}\x1B[0m`); // Display errors in red
      } else if (message.message) {
        terminalInstance.current.write(`${message.message}\n`);
      }
    };

    // Handle terminal input
    terminalInstance.current.onData((input) => {
      if (socketRef.current.readyState === WebSocket.OPEN) {
        socketRef.current.send(JSON.stringify({ containerId, cmd: input })); // Send input to container
      } else {
        terminalInstance.current.write('Connection closed. Unable to send data.\n');
      }
    });

    // Resize terminal when window size changes
    const handleResize = () => fitAddon.current.fit();
    window.addEventListener('resize', handleResize);

    // Cleanup on component unmount
    return () => {
      if (socketRef.current) {
        socketRef.current.close();
      }
      if (terminalInstance.current) {
        terminalInstance.current.dispose();
      }
      window.removeEventListener('resize', handleResize);
    };
  }, [containerId]);

  return (
    <div

      style={{
        width: '100%',
        height: '100%',
        backgroundColor: 'black',
        color: 'white',
      }}
    />
  );
}

export default TerminalComponent;
